    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="13.5" r="7.5" /><path d="M12 10 L12 13.5 L14.5 15 M9 3.5 L15 3.5 M12 3.5 L12 6" />
    </svg>
